/* ---------- Set limit ---------- */
.slx{padding:16px;display:flex;flex-direction:column;gap:14px}
.slx-h{display:flex;align-items:flex-start;justify-content:space-between}
.slx-h>div{display:flex;flex-direction:column;font-size:14px}
.slx-h b{font-weight:500}
.slx-h .muted{font-size:12px}
.slx-v{font-size:24px;font-weight:600!important;letter-spacing:-.02em}
.slx-bar{position:relative;height:12px;border-radius:6px;background:var(--chip);margin:18px 0 6px;touch-action:none;cursor:pointer}
.slx-used{position:absolute;left:0;top:0;bottom:0;border-radius:6px;background:var(--accent);transition:width .8s var(--ease);z-index:1}
.slx-fc{position:absolute;left:0;top:0;bottom:0;border-radius:6px;background:repeating-linear-gradient(-45deg,color-mix(in srgb,var(--accent) 35%,transparent) 0 4px,color-mix(in srgb,var(--accent) 15%,transparent) 4px 8px);transition:width .8s var(--ease)}
.slx-k{position:absolute;top:50%;width:6px;height:26px;margin:-13px 0 0 -3px;border-radius:3px;background:var(--fg);z-index:2;cursor:grab;transition:transform .2s}
.slx-k:hover,.slx-k.drag{box-shadow:0 0 0 4px var(--accent-bg)}
.slx-tt{position:absolute;bottom:calc(100% + 6px);left:50%;transform:translateX(-50%);padding:3px 7px;border-radius:7px;background:var(--ink);color:var(--on-ink);font-size:11px;white-space:nowrap;opacity:0;transition:opacity .2s;pointer-events:none}
.slx-k:hover .slx-tt,.slx-k.drag .slx-tt{opacity:1}
.slx-lg{display:flex;gap:16px;font-size:12px}
.slx-lg span{display:flex;align-items:center;gap:6px}
.slx-lg b{color:var(--fg);font-weight:500}
.slx-lg i{width:8px;height:8px;border-radius:3px}
.slx-lg i.fc{background:color-mix(in srgb,var(--accent) 35%,transparent)}
.slx-warn{font-size:12.5px;min-height:18px}
.slx-warn .w{display:flex;align-items:center;gap:7px;color:var(--warn)}
.slx-warn .o{display:flex;align-items:center;gap:7px;color:var(--ok)}
.slx-opt{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;font-size:12.5px}
.slx-sg button{font-size:12px;height:28px;padding:0 10px}

DM.def('set-limit', (r, c) => {
  const bar = $('.slx-bar', r), k = $('.slx-k', r), tt = $('.slx-tt', r), v = $('.slx-v', r), used = $('.slx-used', r), fc = $('.slx-fc', r), warn = $('.slx-warn', r);
  const MIN = 50, MAX = 500, SPENT = 128, FC = 184; let cap = 200, mode = 'pause';
  const pct = x => (x - MIN) / (MAX - MIN) * 100;
  function upd(anim){
    k.style.left = pct(cap) + '%'; tt.textContent = '$' + cap; v.textContent = '$' + cap; k.setAttribute('aria-valuenow', cap);
    used.style.width = Math.min(100, SPENT / cap * pct(cap)) + '%'; fc.style.width = Math.min(pct(cap), FC / cap * pct(cap)) + '%';
    const over = FC > cap;
    const h = over ? `<span class="w">${I('alert','xs')}Forecast passes your cap around Oct 27. Runs will ${mode === 'pause' ? 'pause' : mode === 'ask' ? 'wait for you' : 'keep going'}.</span>` : `<span class="o">${I('ok','xs')}On track. About $${cap - FC} left at month end.</span>`;
    if (warn.dataset.h !== String(over) + mode){ warn.dataset.h = String(over) + mode; warn.innerHTML = h; enter(warn.firstChild); }
  }
  const at = e => { const b = bar.getBoundingClientRect(); cap = Math.round((MIN + (MAX - MIN) * Math.max(0, Math.min(1, (e.clientX - b.left) / b.width))) / 10) * 10; upd(); };
  bar.onpointerdown = e => { bar.setPointerCapture(e.pointerId); k.classList.add('drag'); at(e); bar.onpointermove = at; };
  bar.onpointerup = bar.onpointercancel = () => { k.classList.remove('drag'); bar.onpointermove = null; };
  k.onkeydown = e => { if (e.key === 'ArrowRight' || e.key === 'ArrowUp'){ cap = Math.min(MAX, cap + 10); upd(); e.preventDefault(); } if (e.key === 'ArrowLeft' || e.key === 'ArrowDown'){ cap = Math.max(MIN, cap - 10); upd(); e.preventDefault(); } };
  seg($('.slx-sg', r), m => { mode = m; upd(); });
  used.style.width = 0; fc.style.width = 0; k.style.left = pct(cap) + '%';
  c.later(200, () => upd());
  c.later(1500, () => tween(200, 170, 900, x => { cap = Math.round(x / 10) * 10; upd(); }));
});
